/* ---------------- STATE (localStorage) ---------------- */
const STORE_KEY = "suadmon_data_v1";
const DEFAULT_STATE = { completedDates:[], favorites:[], prayerHistory:[], customPrayerSets:[], gardenClaims:[], gardenManualMissions:[], gardenActions:[], gardenBonus:0, characterTaps:0, characterGifts:[], selectedGardenItem:"lotus", selectedReward:"lotus-0", gardenDecorations:[], gardenDecorLevel:1, gardenSoundOn:false, goal:21, fontSize:"medium", reminderOn:false, reminderTime:"20:00", continuousOn:false, theme:"purple", profileName:"", profileMessage:"", profileFirstName:"", profileLastName:"", profileGender:"หญิง", profileTheme:"pink", profileBirthDate:"", profileEmail:"", communityFriends:[], encouragementHistory:[], isVip:false, vipPlan:"", soundOn:true, masterVolume:70, chantVolume:80, ambientVolume:60, notificationVolume:70, soundPreset:0, soundContinuous:true, notifyPrayer:true, notifyStreak:true, notifyMissions:true, notifyDailyTip:true, notifyAchievements:true, notifySpecial:true, notifyNews:false, seenBadges:[], notifiedLog:{} };
function loadState(){
  try{
    const raw = localStorage.getItem(STORE_KEY);
    if(raw){
      const saved = JSON.parse(raw);
      return {...DEFAULT_STATE,...saved,customPrayerSets:Array.isArray(saved.customPrayerSets)?saved.customPrayerSets:[]};
    }
  }catch(e){}
  return {...DEFAULT_STATE,completedDates:[],favorites:[],prayerHistory:[],customPrayerSets:[]};
}
function saveState(onSync){ localStorage.setItem(STORE_KEY, JSON.stringify(state)); queueCloudStateSync(onSync); queueLinePreferenceSync(); }
let state = loadState();
// สถานะกำลังเล่นเป็นสถานะชั่วคราว: เปิดแอปใหม่ต้องไม่เล่นเสียงเอง
state.gardenSoundOn=false;

/* ---------------- AUTH / CLOUD SYNC ---------------- */
let supabaseClient=null;
let cloudSyncTimer=null;
let authMode="register";
let authSession=null;
const LINE_BOT_API="https://suanboon-line-bot-fearbongz.vercel.app";
let linePreferenceTimer;

function queueLinePreferenceSync(){
  if(!authSession?.access_token)return;
  clearTimeout(linePreferenceTimer);
  linePreferenceTimer=setTimeout(async()=>{
    const allowedTimes=["20:00","21:00","22:00"];
    const prayerTime=allowedTimes.includes(state.reminderTime)?state.reminderTime:"20:00";
    try{
      await fetch(`${LINE_BOT_API}/api/preferences`,{method:"POST",headers:{Authorization:`Bearer ${authSession.access_token}`,"Content-Type":"application/json"},body:JSON.stringify({prayer_time:prayerTime,notify_prayer:state.reminderOn&&state.notifyPrayer!==false,notify_streak:state.notifyStreak!==false,notify_level_up:state.notifyAchievements!==false,notify_encouragement:true,notify_weekly:true})});
    }catch(error){console.warn("LINE preference sync failed",error);}
  },800);
}

async function attemptLineAccountLink(session){
  const token=new URLSearchParams(location.search).get("line_link");
  if(!token||!session?.access_token)return;
  const attemptKey=`suadmon_line_link_${token}`;
  const url=new URL(location.href);url.searchParams.delete("line_link");history.replaceState({},"",url);
  if(sessionStorage.getItem(attemptKey))return;
  sessionStorage.setItem(attemptKey,"working");
  try{
    const response=await fetch(`${LINE_BOT_API}/api/link-account`,{method:"POST",headers:{Authorization:`Bearer ${session.access_token}`,"Content-Type":"application/json"},body:JSON.stringify({token})});
    const result=await response.json().catch(()=>({}));
    if(!response.ok)throw new Error(result.error||"เชื่อมบัญชีไม่สำเร็จ");
    sessionStorage.setItem(attemptKey,"done");
    queueLinePreferenceSync();
    showLineLinkMessage("เชื่อมบัญชีสำเร็จ",true);
  }catch(error){
    sessionStorage.setItem(attemptKey,"failed");
    const message=error.message==="Link expired or already used"?"ลิงก์เชื่อมบัญชีหมดอายุแล้ว กรุณาเปิด LINE และเชื่อมบัญชีใหม่ค่ะ":error.message==="Please sign in first"?"กรุณาเข้าสู่ระบบก่อน แล้วเชื่อมบัญชีจากหน้าตั้งค่าใหม่ค่ะ":error.message;
    showLineLinkMessage(message,false);
  }
}

function showLineLinkMessage(message,notifyLine=false){
  const modal=document.getElementById("lineLinkSuccessModal"),title=document.getElementById("lineLinkSuccessTitle"),ok=document.getElementById("lineLinkSuccessOk");
  if(!modal||!title||!ok)return;
  title.textContent=message;
  ok.dataset.notifyLine=notifyLine?"true":"false";
  modal.classList.add("open");
}

async function sendLineEvent(type,payload={}){
  if(!authSession?.access_token)return;
  try{
    await fetch(`${LINE_BOT_API}/api/events`,{method:"POST",headers:{Authorization:`Bearer ${authSession.access_token}`,"Content-Type":"application/json"},body:JSON.stringify({type,...payload})});
  }catch(error){console.warn("LINE event notification failed",error);}
}

function getSupabaseClient(){
  if(supabaseClient) return supabaseClient;
  const config=window.SUPABASE_CONFIG || {};
  if(!config.url||!config.publishableKey||!window.supabase?.createClient) return null;
  supabaseClient=window.supabase.createClient(config.url,config.publishableKey);
  return supabaseClient;
}

async function pushCloudState(onComplete){
  try{
    const client=getSupabaseClient();
    if(!client){onComplete?.({saved:false,reason:"offline"});return;}
    const {data:{user},error:userError}=await client.auth.getUser();
    if(userError)throw userError;
    if(!user){onComplete?.({saved:false,reason:"guest"});return;}
    const {error}=await client.from("user_state").upsert({user_id:user.id,data:state,updated_at:new Date().toISOString()});
    if(error)throw error;
    onComplete?.({saved:true});
  }catch(error){console.warn("Cloud state sync failed:",error);onComplete?.({saved:false,reason:"error",error});}
}

function queueCloudStateSync(onComplete){
  clearTimeout(cloudSyncTimer);
  cloudSyncTimer=setTimeout(()=>{cloudSyncTimer=null;pushCloudState(onComplete);},700);
}

// เผื่อผู้ใช้ปิดแท็บ/สลับแอปก่อนครบ 700ms ของ debounce ด้านบน ให้ยิง sync ทันที
// ไม่งั้นข้อมูล (เช่นวันที่สวดมนต์ล่าสุด) จะค้างอยู่แค่ใน localStorage เครื่องนี้ ไม่ขึ้นคลาวด์
function flushCloudStateSync(){
  if(cloudSyncTimer){clearTimeout(cloudSyncTimer);cloudSyncTimer=null;pushCloudState();}
}
if(typeof document!=="undefined"){
  document.addEventListener("visibilitychange",()=>{if(document.hidden)flushCloudStateSync();});
  window.addEventListener("pagehide",flushCloudStateSync);
  window.addEventListener("beforeunload",flushCloudStateSync);
}

// รวม array ประเภทวัน/ประวัติของ local (เครื่องนี้) กับ cloud (บัญชี) แบบ union
// กันเคสที่เครื่องนี้สวดมนต์ไว้แล้วแต่ยังไม่ทันซิงก์ขึ้นคลาวด์ (เช่นปิดแอปเร็วไป)
// แล้วพอ login เครื่องอื่น/เครื่องนี้ใหม่ ข้อมูลที่สวดไปแล้วถูกทับหายไป
function unionByKey(localArr,cloudArr){
  const local=Array.isArray(localArr)?localArr:[];
  const cloud=Array.isArray(cloudArr)?cloudArr:[];
  const seen=new Set();
  const out=[];
  [...local,...cloud].forEach(item=>{
    const key=typeof item==="object"&&item!==null?JSON.stringify(item):String(item);
    if(!seen.has(key)){seen.add(key);out.push(item);}
  });
  return out;
}
const CLOUD_MERGE_ARRAY_FIELDS=["completedDates","favorites","prayerHistory","customPrayerSets","gardenClaims","gardenManualMissions","gardenActions","characterGifts","communityFriends","encouragementHistory","seenBadges","gardenDecorations"];
const CLOUD_MERGE_MAX_NUMBER_FIELDS=["gardenBonus","characterTaps","lotusSpent","gardenDecorLevel"];
function mergeCloudState(localState,cloudData){
  const merged={...DEFAULT_STATE,...localState,...cloudData};
  CLOUD_MERGE_ARRAY_FIELDS.forEach(key=>{merged[key]=unionByKey(localState[key],cloudData[key]);});
  CLOUD_MERGE_MAX_NUMBER_FIELDS.forEach(key=>{merged[key]=Math.max(Number(localState[key])||0,Number(cloudData[key])||0);});
  return merged;
}

async function loadCloudState(){
  const client=getSupabaseClient();
  if(!client) return false;
  const {data:{user}}=await client.auth.getUser();
  if(!user) return false;
  const {data}=await client.from("user_state").select("data").eq("user_id",user.id).maybeSingle();
  if(data?.data){
    const merged=mergeCloudState(state,data.data);
    state=merged;
    localStorage.setItem(STORE_KEY,JSON.stringify(state));
    renderAll();
    queueCloudStateSync(); // เขียนผลรวมกลับขึ้นคลาวด์ ให้ทุกเครื่องเห็นข้อมูลชุดล่าสุดตรงกัน
  }
  else queueCloudStateSync();
  // เติมข้อมูลโปรไฟล์จากตอนสมัครสมาชิกให้ครั้งแรก (ไม่ทับถ้าผู้ใช้เคยแก้ไขเองแล้ว)
  const meta=user.user_metadata||{};
  if(!state.profileName&&meta.full_name || !state.profileBirthDate&&meta.birth_date || !state.profileGender&&meta.gender || !state.profileEmail&&user.email){
    state.profileName=state.profileName||meta.full_name||"";
    state.profileBirthDate=state.profileBirthDate||meta.birth_date||"";
    state.profileGender=state.profileGender||meta.gender||"";
    state.profileEmail=state.profileEmail||user.email||"";
    saveState();
    renderAll();
  }
  return true;
}

function translateAuthError(message=""){
  if(/email not confirmed/i.test(message)) return "ยังไม่ได้ยืนยันอีเมล กรุณากดลิงก์ยืนยันในอีเมลที่เราส่งให้ก่อนเข้าสู่ระบบนะคะ";
  if(/invalid login credentials/i.test(message)) return "อีเมล/เบอร์โทร หรือรหัสผ่านไม่ถูกต้อง";
  if(/user already registered/i.test(message)) return "อีเมลนี้เคยสมัครสมาชิกไว้แล้ว กรุณาเข้าสู่ระบบแทน";
  if(/password should be at least/i.test(message)) return "รหัสผ่านต้องมีอย่างน้อย 8 ตัวอักษร";
  if(/rate limit/i.test(message)) return "ลองบ่อยเกินไป กรุณารอสักครู่แล้วลองใหม่";
  return message||"ไม่สามารถเชื่อมต่อระบบสมาชิกได้ กรุณาลองใหม่";
}

