function renderTiles(){
  const wrap = document.getElementById("quickTiles");
  wrap.innerHTML = QUICK_TILES.map(t=>`
    <button class="tile" data-open="${t.id}">
      <img src="${t.icon}" alt="">
      <span>${t.label}</span>
    </button>
  `).join("");
  wrap.querySelectorAll("[data-open]").forEach(btn=>{
    btn.addEventListener("click", ()=>{
      if(btn.dataset.open==="saved-prayers"){
        showScreen("merit");
        setTimeout(()=>document.getElementById("favoritesSection")?.scrollIntoView({behavior:"smooth",block:"start"}),250);
        return;
      }
      openReader(btn.dataset.open);
    });
  });
}

/* ---------------- HOME: STREAK ---------------- */
function renderStreak(){
  const streak = computeStreak();
  document.getElementById("streakNum").textContent = streak;
  document.getElementById("goalDays").textContent = state.goal;
  document.getElementById("meritStreak").textContent = streak;

  const cheer = document.getElementById("streakCheer");
  if(streak===0) cheer.textContent = "เริ่มต้นวันนี้เลยนะคะ";
  else if(streak<7) cheer.textContent = "เก่งมากเลยค่ะ! ✨";
  else if(streak<21) cheer.textContent = "สุดยอดไปเลยค่ะ! 🔥";
  else cheer.textContent = "สม่ำเสมอสุด ๆ ค่ะ! 🏵️";

  const week = document.getElementById("streakWeek");
  const now = new Date();
  const monIdx = dowMon0(now);
  const monday = new Date(now); monday.setDate(now.getDate()-monIdx);
  const set = new Set(state.completedDates);

  let html="";
  for(let i=0;i<7;i++){
    const d = new Date(monday); d.setDate(monday.getDate()+i);
    const ds = todayStr(d);
    const isToday = ds===todayStr(now);
    const isFuture = d > now && !isToday;
    const done = set.has(ds);
    let cls = "day-badge";
    let content = "";
    if(done){ cls+=" done"; content="✓"; }
    else if(isFuture){ cls+=" future"; content=""; }
    if(isToday) cls+=" today";
    const todayAttr = isToday ? `data-today-toggle="1"` : "";
    html += `<div class="day-col"><div class="${cls}" ${todayAttr}>${content}</div><span class="day-label">${DOW_TH[i]}</span></div>`;
  }
  week.innerHTML = html;

  const todayCircle = week.querySelector('[data-today-toggle]');
  if(todayCircle) todayCircle.addEventListener("click", toggleTodayDirect);

  // manual "check in without opening the app's reader" button
  const doneToday = set.has(todayStr(now));
  const btn = document.getElementById("checkinBtn");
  const icon = document.getElementById("checkinIcon");
  const text = document.getElementById("checkinText");
  btn.classList.toggle("done", doneToday);
  icon.textContent = doneToday ? "💗" : "✅";
  text.textContent = doneToday ? "วันนี้สวดแล้วนะคะ (กดอีกครั้งเพื่อยกเลิก)" : "วันนี้สวดแล้ว ไม่ผ่านแอป กดติ๊กเลย";
}

/* ---------------- PRAYER LIBRARY ---------------- */
let activeCategory = "ทั้งหมด";
let searchTerm = "";
let activeLibraryTab = "all";
let editingPrayerSetId = null;
let editingPrayerSetDraft = [];
let editingAssistantSetId = null;
let assistantPrayerOrder = [];

function renderChips(){
  const row = document.getElementById("chipRow");
  row.innerHTML = CATEGORIES.map(c=>`<button class="chip ${c===activeCategory?"active":""}" data-cat="${c}">${c}</button>`).join("");
  row.querySelectorAll("[data-cat]").forEach(btn=>{
    btn.addEventListener("click", ()=>{ activeCategory = btn.dataset.cat; renderChips(); renderPrayerList(); });
  });
}

function renderPrayerList(){
  const list = document.getElementById("prayerList");
  let items = PRAYERS.filter(prayer=>prayer.id!=="popular").sort((a,b)=>b.popularity-a.popularity);
  if(activeCategory!=="ทั้งหมด") items = items.filter(p=>p.category===activeCategory);
  if(searchTerm.trim()) items = items.filter(p=>p.title.includes(searchTerm.trim()));

  if(items.length===0){
    list.innerHTML = `<p class="no-results">ไม่พบบทสวดที่ค้นหาค่ะ 🥲</p>`;
    return;
  }
  list.innerHTML = items.map(p=>prayerCardHTML(p)).join("");
  bindPrayerCards(list);
}

function renderMyPrayerSets(){
  const wrap = document.getElementById("myPrayerSets");
  const empty = document.getElementById("myPrayerEmpty");
  const detail = document.getElementById("myPrayerDetail");
  const sets = Array.isArray(state.customPrayerSets) ? [...state.customPrayerSets].reverse() : [];
  detail.classList.remove("open");
  wrap.style.display = sets.length ? "flex" : "none";
  empty.style.display = sets.length ? "none" : "block";
  wrap.innerHTML = sets.map(set=>`<button class="my-set-card" data-set-id="${set.id}"><span class="my-set-icon"><img src="assets/assistant-calm.png" alt=""></span><span class="my-set-copy"><b>${set.name}</b><small>${set.prayerIds.length} บท · ใช้เวลาประมาณ ${set.totalMinutes || 0} นาที</small></span><span class="my-set-arrow">›</span></button>`).join("");
  wrap.querySelectorAll("[data-set-id]").forEach(button=>button.addEventListener("click",()=>openMyPrayerSet(button.dataset.setId)));
}

function editPrayerSetInAssistant(setId){
  const set = (state.customPrayerSets || []).find(item=>String(item.id)===String(setId));
  if(!set) return;
  editingAssistantSetId = set.id;
  showScreen("assistant");
  document.querySelector('#assistantModeTabs [data-mode="prayers"]')?.click();
  document.querySelectorAll("#assistantPrayerPicker button.active").forEach(button=>button.classList.remove("active"));
  assistantPrayerOrder = [];
  set.prayerIds.forEach(prayerId=>document.querySelector(`#assistantPrayerPicker button[data-value="${prayerId}"]`)?.click());
  // Keep the saved sequence authoritative every time the same set is reopened.
  assistantPrayerOrder = [...set.prayerIds];
  document.getElementById("assistantPreviewTitle").textContent = set.name;
  document.getElementById("assistantResult").classList.remove("show");
  document.getElementById("assistantCreate").innerHTML = '<span>✦</span> บันทึกการแก้ไข <small>อัปเดตชุดสวดของฉัน</small>';
}

function openMyPrayerSet(setId){
  const set = (state.customPrayerSets || []).find(item=>String(item.id)===String(setId));
  if(!set) return;
  editingPrayerSetId = set.id;
  editingPrayerSetDraft = [...set.prayerIds];
  document.getElementById("myPrayerSets").style.display = "none";
  document.getElementById("myPrayerEmpty").style.display = "none";
  document.getElementById("myPrayerDetail").classList.add("open");
  document.getElementById("myPrayerDetailTitle").textContent = set.name;
  renderMyPrayerSetEditor();
}

function openPlaylistRenameModal(){
  const set=(state.customPrayerSets||[]).find(item=>String(item.id)===String(editingPrayerSetId));
  if(!set)return;
  const modal=document.getElementById("playlistRenameModal"),input=document.getElementById("playlistRenameInput");
  input.value=set.name||"";modal.classList.add("open");setTimeout(()=>{input.focus();input.select();},50);
}

function savePlaylistRename(){
  const set=(state.customPrayerSets||[]).find(item=>String(item.id)===String(editingPrayerSetId));
  const input=document.getElementById("playlistRenameInput"),name=input.value.trim();
  if(!set||!name){input.focus();return;}
  set.name=name;saveState();document.getElementById("myPrayerDetailTitle").textContent=name;document.getElementById("playlistRenameModal").classList.remove("open");
}

async function openPlaylistShareModal(){
  const set=(state.customPrayerSets||[]).find(item=>String(item.id)===String(editingPrayerSetId));
  if(!set)return;
  await refreshCommunityFriends();
  const modal=document.getElementById("playlistShareModal"),wrap=document.getElementById("playlistShareFriends");
  document.getElementById("playlistShareName").textContent=`“${set.name}” · ${set.prayerIds.length} บท`;
  const escape=value=>String(value??"").replace(/[&<>'"]/g,char=>({"&":"&amp;","<":"&lt;",">":"&gt;","'":"&#39;",'"':"&quot;"})[char]);
  wrap.innerHTML=state.communityFriends.length?state.communityFriends.map(friend=>`<button type="button" data-share-friend="${escape(friend.user_id)}"><img src="${encouragementAvatar(friend)}" alt=""><span><b>${escape(friend.full_name||"เพื่อนสายบุญ")}</b><small>แตะเพื่อส่งในชุมชน</small></span></button>`).join(""):'<p>ยังไม่มีเพื่อนในชุมชนค่ะ</p>';
  wrap.querySelectorAll("[data-share-friend]").forEach(button=>button.onclick=async()=>{
    button.disabled=true;
    const client=getSupabaseClient();
    const {error}=await client.from("prayer_playlist_shares").insert({recipient_id:button.dataset.shareFriend,sender_name:state.profileName||"เพื่อนสายบุญ",playlist_name:set.name,prayer_ids:set.prayerIds});
    if(error){button.disabled=false;button.querySelector("small").textContent="ส่งไม่สำเร็จ กรุณาลองใหม่";return;}
    button.querySelector("small").textContent="✓ ส่งแล้ว";
    setTimeout(()=>modal.classList.remove("open"),700);
  });
  modal.classList.add("open");
}

function renderMyPrayerSetEditor(){
  const prayers = editingPrayerSetDraft.map(findPrayer).filter(Boolean);
  document.getElementById("myPrayerDetailMeta").textContent = `${prayers.length} บท`;
  const list = document.getElementById("myPrayerDetailList");
  list.innerHTML = prayers.map((prayer,index)=>{
    const isFav = state.favorites.includes(prayer.id);
    return `<button class="my-prayer-item" data-open="${prayer.id}"><i>${index+1}</i><img src="${getPrayerIcon(prayer)}" alt=""><span><b>${prayer.title}</b><small>${prayer.duration}</small></span><em class="pc-fav ${isFav ? "active" : ""}" data-fav="${prayer.id}" aria-label="บันทึกบทสวด">${FAVORITE_HEART_ICON}</em></button>`;
  }).join("");
  list.querySelectorAll("[data-open]").forEach(button=>button.addEventListener("click",event=>{
    if(event.target.closest("[data-fav]")) return;
    openReaderFromSet(button.dataset.open);
  }));
  list.querySelectorAll("[data-fav]").forEach(button=>button.addEventListener("click",event=>{
    event.stopPropagation();
    toggleFavorite(button.dataset.fav);
    renderMyPrayerSetEditor();
  }));
}

function openReaderFromSet(prayerId){
  activeReaderSequence = editingPrayerSetDraft.map(findPrayer).filter(Boolean).map(prayer=>prayer.id);
  activeReaderSequenceIndex = activeReaderSequence.indexOf(prayerId);
  openReader(prayerId,{preserveSequence:true});
}

function deleteMyPrayerSet(setId){
  if(!confirm("ต้องการลบชุดสวดนี้ใช่ไหม?")) return;
  state.customPrayerSets = (state.customPrayerSets || []).filter(item=>String(item.id)!==String(setId));
  saveState();
  renderMyPrayerSets();
}

function setPrayerLibraryTab(tab){
  activeLibraryTab = tab;
  document.querySelectorAll("#prayerLibraryTabs button").forEach(button=>button.classList.toggle("active",button.dataset.libraryTab===tab));
  document.getElementById("allPrayersPanel").style.display = tab==="all" ? "block" : "none";
  document.getElementById("myPrayersPanel").classList.toggle("active",tab==="mine");
  if(tab==="mine") renderMyPrayerSets();
}

function prayerCardHTML(p){
  const isFav = state.favorites.includes(p.id);
  const prayerIcon = getPrayerIcon(p);
  return `
    <button class="prayer-card" data-open="${p.id}">
      <div class="pc-icon-wrap ${prayerIcon === "assets/prayer-hands.png" ? "pc-icon-hands" : ""}" style="background-image:url('${prayerIcon}')"></div>
      <div class="pc-body">
        <div class="pc-title-row">
          <h3>${p.title}</h3>
          ${p.badge ? `<span class="pc-tag">${p.badge}</span>` : ""}
        </div>
        <p class="pc-desc">${p.desc || ""}</p>
        <div class="pc-meta">
          <span class="pc-time"><svg class="meta-icon" viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/></svg>${p.duration}</span>
          <span class="pc-popularity"><svg class="meta-icon meta-person" viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="8" r="4"/><path d="M5 21a7 7 0 0 1 14 0Z"/></svg>ยอดสวด ${p.popularity.toLocaleString()} ครั้ง</span>
        </div>
      </div>
      <span class="pc-actions">
        <span class="pc-fav ${isFav ? "active" : ""}" data-fav="${p.id}">${FAVORITE_HEART_ICON}</span>
        <span class="pc-play"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M8 5v14l11-7Z"/></svg></span>
      </span>
    </button>
  `;
}

function bindPrayerCards(container){
  container.querySelectorAll("[data-open]").forEach(card=>{
    card.addEventListener("click", (e)=>{
      if(e.target.closest("[data-fav]")) return;
      openReader(card.dataset.open);
    });
  });
  container.querySelectorAll("[data-fav]").forEach(el=>{
    el.addEventListener("click", (e)=>{
      e.stopPropagation();
      toggleFavorite(el.dataset.fav);
    });
  });
}

function toggleFavorite(id){
  const i = state.favorites.indexOf(id);
  if(i>-1) state.favorites.splice(i,1); else state.favorites.push(id);
  saveState();
  renderPrayerList();
  renderFavList();
  renderMeritStats();
  if(currentPrayer && currentPrayer.id===id) updateFavIcon();
}

/* ---------------- MERIT SCREEN ---------------- */
function renderMeritStats(){
  const streak = computeStreak();
  document.getElementById("meritStreak").textContent = streak;
  document.getElementById("meritTotal").textContent = state.completedDates.length;
  document.getElementById("meritStreakDetail").textContent = streak;
  document.getElementById("meritFav").textContent = state.favorites.length;
  const now = new Date();
  const monday = new Date(now); monday.setDate(now.getDate()-dowMon0(now));
  const completed = new Set(state.completedDates);
  document.getElementById("meritWeek").innerHTML = DOW_TH.map((label,i)=>{
    const day = new Date(monday); day.setDate(monday.getDate()+i);
    const done = completed.has(todayStr(day));
    const future = day > now;
    return `<span class="merit-day"><b>${label}</b><i class="${done ? "done" : future ? "future" : ""}">${done ? "✓" : ""}</i></span>`;
  }).join("");
}

function renderCalendar(){
  const cal = document.getElementById("calendar");
  const now = new Date();
  const y = now.getFullYear(), m = now.getMonth();
  const firstDow = dowMon0(new Date(y,m,1));
  const daysInMonth = new Date(y,m+1,0).getDate();
  const set = new Set(state.completedDates);

  let html = DOW_TH.map(d=>`<div class="cal-dow">${d}</div>`).join("");
  for(let i=0;i<firstDow;i++) html += `<div class="cal-day empty"></div>`;
  for(let day=1; day<=daysInMonth; day++){
    const ds = todayStr(new Date(y,m,day));
    const isToday = ds===todayStr(now);
    const done = set.has(ds);
    html += `<div class="cal-day ${done?"done":""} ${isToday?"today":""}">${day}</div>`;
  }
  cal.innerHTML = html;
}

function renderBadges(){
  const streak = computeStreak();
  const total = state.completedDates.length;
  const fav = state.favorites.length;
  const seen = Array.isArray(state.seenBadges) ? state.seenBadges : (state.seenBadges=[]);
  let newlyUnlocked=false;
  BADGES.forEach(b=>{
    const val = b.type==="streak"?streak : b.type==="fav"?fav : total;
    if(val>=b.need && !seen.includes(b.id)){
      seen.push(b.id);
      newlyUnlocked=true;
      if(state.notifyAchievements) notifyUser("ปลดล็อกความสำเร็จใหม่! ✨",b.label);
    }
  });
  if(newlyUnlocked) saveState();
  const grid = document.getElementById("badgeGrid");
  if(!grid) return;
  grid.innerHTML = BADGES.map(b=>{
    const val = b.type==="streak"?streak : b.type==="fav"?fav : total;
    const unlocked = val>=b.need;
    return `<div class="badge-item ${unlocked?"":"locked"}">
      <span class="b-icon">${b.icon}</span>
      <span class="b-label">${b.label}</span>
    </div>`;
  }).join("");
}

let showAllFavorites = false;

function renderFavList(){
  const list = document.getElementById("favList");
  const empty = document.getElementById("favEmpty");
  const showAllButton = document.getElementById("favoritesShowAll");
  const favs = PRAYERS.filter(p=>state.favorites.includes(p.id));
  if(favs.length===0){
    list.innerHTML=""; empty.style.display="block"; showAllButton.style.display="none"; return;
  }
  empty.style.display="none";
  const visibleFavorites = showAllFavorites ? favs : favs.slice(0,5);
  list.innerHTML = visibleFavorites.map(p=>prayerCardHTML(p)).join("");
  showAllButton.style.display = favs.length>5 ? "block" : "none";
  showAllButton.textContent = showAllFavorites ? "แสดงน้อยลง" : `แสดงทั้งหมด (${favs.length})`;
  bindPrayerCards(list);
}

function bindFavorites(){
  document.getElementById("favoritesShowAll").addEventListener("click",()=>{
    showAllFavorites = !showAllFavorites;
    renderFavList();
  });
}

/* ---------------- READER OVERLAY ---------------- */
let currentPrayer = null;
let readerTimer = null;
let currentLine = 0;
let isPlaying = false;
let activeReaderTab = "prayer";
let activeReaderSequence = [];
let activeReaderSequenceIndex = -1;
let readerRoundCount = 0;
let readerMediaMode = "text";
const LINE_SECONDS = 3.2;
const FAVORITE_HEART_ICON = '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8l1.1 1.1L12 21l7.8-7.5 1.1-1.1a5.5 5.5 0 0 0-.1-7.8Z"/></svg>';

function getPrayerRoundTarget(prayer){
  const text=[prayer?.badge,prayer?.readerHeading,...(prayer?.lines || [])].filter(Boolean).join(" ");
  const match=text.match(/([0-9๐-๙]+)\s*จบ/);
  if(!match) return 0;
  const thaiDigits="๐๑๒๓๔๕๖๗๘๙";
  return Number([...match[1]].map(char=>thaiDigits.includes(char) ? thaiDigits.indexOf(char) : char).join("")) || 0;
}

function resetReaderRoundCounter(){
  readerRoundCount=0;
  document.getElementById("readerRoundCount").textContent="0";
  const target=getPrayerRoundTarget(currentPrayer);
  document.getElementById("readerRoundTarget").textContent=target ? ` / ${target}` : "";
}

function openReader(id,options={}){
  if(!options.preserveSequence){ activeReaderSequence=[]; activeReaderSequenceIndex=-1; }
  currentPrayer = findPrayer(id);
  if(!currentPrayer) return;
  currentLine = 0;
  isPlaying = false;
  clearInterval(readerTimer);

  document.getElementById("readerCat").textContent = currentPrayer.category;
  document.getElementById("readerTitle").textContent = currentPrayer.title;
  document.getElementById("readerImage").src = getPrayerIcon(currentPrayer);
  document.getElementById("readerPrayerHeading").textContent = currentPrayer.readerHeading || currentPrayer.title;
  document.getElementById("readerDesc").textContent = currentPrayer.desc || "";
  document.getElementById("readerDuration").textContent = currentPrayer.duration;
  document.getElementById("readerPop").textContent = currentPrayer.popularity.toLocaleString();
  setupReaderYoutube();
  document.querySelector('[data-reader-tab="advice"]')?.classList.toggle("has-closing-prayer",getReaderClosingPrayerLines().length>0);
  resetReaderRoundCounter();
  updateFavIcon();
  renderReaderLines();
  setReaderTab("prayer");
  updateProgress();
  setPlayIcon(false);
  updateReaderSetNav();

  showScreen("reader");
  document.querySelectorAll(".nav-item").forEach(b=>b.classList.remove("active"));
  document.getElementById("mainPrayerBtn").classList.add("active");
  fitReaderRibbon();
}

function setupReaderYoutube(){
  const switcher=document.getElementById("readerMediaSwitch");
  const frame=document.getElementById("readerYoutubeFrame");
  const hasYoutube=Boolean(currentPrayer?.youtubeId);
  const startAt=Number(currentPrayer?.youtubeStart) || 0;
  switcher.hidden=!hasYoutube;
  frame.innerHTML=hasYoutube
    ? `<iframe title="YouTube ${currentPrayer.title}" src="https://www.youtube-nocookie.com/embed/${currentPrayer.youtubeId}?enablejsapi=1&playsinline=1&rel=0${startAt ? `&start=${startAt}` : ""}" referrerpolicy="strict-origin-when-cross-origin" allow="autoplay; encrypted-media; picture-in-picture" allowfullscreen></iframe><a class="reader-youtube-external" href="https://www.youtube.com/watch?v=${currentPrayer.youtubeId}${startAt ? `&t=${startAt}s` : ""}" target="_blank" rel="noopener noreferrer">เปิดบน YouTube ↗</a>`
    : "";
  setReaderMediaMode("text");
}

function setReaderMediaMode(mode){
  readerMediaMode=mode;
  document.querySelector(".reader-text-wrap").classList.toggle("youtube-mode",mode==="youtube");
  document.querySelectorAll("[data-reader-media]").forEach(button=>{
    button.classList.toggle("active",button.dataset.readerMedia===mode);
    button.setAttribute("aria-pressed",String(button.dataset.readerMedia===mode));
  });
}

function commandReaderYoutube(command,args=[]){
  const iframe=document.querySelector("#readerYoutubeFrame iframe");
  iframe?.contentWindow?.postMessage(JSON.stringify({event:"command",func:command,args}),"*");
}

/* ชื่อบทที่ยาว (หรือเครื่องที่ตั้งขนาดตัวอักษรใหญ่) จะขึ้นหลายบรรทัด
   เลยต้องดันเนื้อบทลงตามความสูงจริงของป้าย ไม่ให้ทับกัน */
function fitReaderRibbon(){
  const ribbon=document.getElementById("readerPrayerHeading");
  const wrap=document.querySelector(".reader-text-wrap");
  if(!ribbon||!wrap) return;
  wrap.style.paddingTop=`${Math.max(56,ribbon.offsetHeight+24)}px`;
}

function updateReaderSetNav(){
  const nav = document.getElementById("readerSetNav");
  const hasSequence = activeReaderSequence.length > 0 && activeReaderSequenceIndex >= 0;
  nav.classList.toggle("open",hasSequence);
  if(!hasSequence) return;
  const previous = findPrayer(activeReaderSequence[activeReaderSequenceIndex-1]);
  const next = findPrayer(activeReaderSequence[activeReaderSequenceIndex+1]);
  document.getElementById("readerSetPosition").textContent = `${activeReaderSequenceIndex+1} / ${activeReaderSequence.length}`;
  document.getElementById("readerSetPrevName").textContent = previous?.title || "บทแรก";
  document.getElementById("readerSetNextName").textContent = next?.title || "บทสุดท้าย";
  document.getElementById("readerSetPrev").disabled = !previous;
  document.getElementById("readerSetNext").disabled = !next;
}

function navigateReaderSet(direction){
  const nextIndex = activeReaderSequenceIndex + direction;
  if(nextIndex < 0 || nextIndex >= activeReaderSequence.length) return;
  activeReaderSequenceIndex = nextIndex;
  openReader(activeReaderSequence[nextIndex],{preserveSequence:true});
}

function setReaderTab(tab){
  activeReaderTab = tab;
  document.querySelectorAll("[data-reader-tab]").forEach(btn=>{
    btn.classList.toggle("active", btn.dataset.readerTab===tab);
  });
  if(tab==="prayer"){
    renderReaderLines();
  }else if(tab==="translation"){
    renderReaderTranslation();
  }else{
    renderReaderClosingPrayer();
  }
}

function isReaderTranslationLine(line){
  const text = String(line || "").trim();
  return text.startsWith("ความหมายโดยย่อ:") ||
    text.startsWith("คำแปล:") ||
    /^\((?:ขอให้|แปลว่า|หมายถึง)/.test(text);
}

function getReaderPrayerLines(){
  const lines = currentPrayer?.lines || [];
  const closingStart = lines.findIndex(line=>String(line).includes("คำอธิษฐานหลังสวด"));
  const prayerLines = closingStart>=0 ? lines.slice(0,closingStart) : lines;
  const visibleLines = prayerLines.filter(line=>!isReaderTranslationLine(line));
  const hasNamo = visibleLines.some(line=>String(line).includes("นะโม ตัสสะ ภะคะวะโต อะระหะโต สัมมาสัมพุทธัสสะ"));
  if(!currentPrayer?.readerHeading && !hasNamo){
    visibleLines.unshift("นะโม ตัสสะ ภะคะวะโต อะระหะโต สัมมาสัมพุทธัสสะ (3 จบ)");
  }
  return visibleLines;
}

function getReaderClosingPrayerLines(){
  const lines = currentPrayer?.lines || [];
  const closingStart = lines.findIndex(line=>String(line).includes("คำอธิษฐานหลังสวด"));
  return closingStart>=0 ? lines.slice(closingStart+1) : [];
}

function getReaderTranslationLines(){
  if(!currentPrayer) return [];
  if(Array.isArray(currentPrayer.translation)) return currentPrayer.translation;
  if(currentPrayer.translation) return [currentPrayer.translation];

  const result = [];
  let section = "";
  let addedSection = "";
  (currentPrayer.lines || []).forEach(line=>{
    if(String(line).startsWith("## ")){
      section = line;
      return;
    }
    if(!isReaderTranslationLine(line)) return;
    if(section && section!==addedSection){
      result.push(section);
      addedSection = section;
    }
    result.push(line);
  });
  return result;
}

function renderReaderTranslation(){
  const translations = getReaderTranslationLines();
  const lines = translations.length ? translations : [currentPrayer.desc || "ยังไม่มีคำแปลสำหรับบทสวดนี้"];
  document.getElementById("readerText").innerHTML = lines.map(line=>{
    const isSection = String(line).startsWith("## ");
    const text = isSection ? String(line).slice(3) : String(line).replace(/^\((.*)\)$/,"$1");
    return `<p class="reader-line current${isSection ? " reader-section-title" : " reader-meaning"}">${text}</p>`;
  }).join("");
}

function renderReaderClosingPrayer(){
  const closingLines = getReaderClosingPrayerLines();
  const lines = closingLines.length ? closingLines : ["บทสวดนี้ยังไม่มีคำอธิษฐานหลังสวด"];
  document.getElementById("readerText").innerHTML = lines.map(line=>{
    const isSection = String(line).startsWith("## ");
    const text = isSection ? String(line).slice(3) : String(line).replace(/^คำแนะนำ:\s*/,"");
    return `<p class="reader-line current${isSection ? " reader-section-title" : ""}">${text}</p>`;
  }).join("");
}

function closeReader(){
  clearInterval(readerTimer);
  commandReaderYoutube("stopVideo");
  isPlaying = false;
  setPlayIcon(false);
  showScreen("prayers");
}

function updateFavIcon(){
  const btn = document.getElementById("readerFav");
  const isFavorite=state.favorites.includes(currentPrayer.id);
  btn.classList.toggle("active",isFavorite);
  btn.setAttribute("aria-pressed",String(isFavorite));
}

function renderReaderLines(){
  const wrap = document.getElementById("readerText");
  const prayerLines = getReaderPrayerLines();
  wrap.innerHTML = prayerLines.map((l,i)=>{
    let cls = "reader-line";
    const isSection = l.startsWith("## ");
    if(isSection) cls += " reader-section-title";
    if(i<currentLine) cls+=" past";
    if(i===currentLine) cls+=" current";
    return `<p class="${cls}" data-line="${i}">${isSection ? l.slice(3) : l}</p>`;
  }).join("");
  const cur = wrap.querySelector(".current");
  if(cur) cur.scrollIntoView({block:"center", behavior:"smooth"});
}

function updateProgress(){
  const prayerLines = getReaderPrayerLines();
  const pct = prayerLines.length<=1 ? 100 : Math.round((currentLine/(prayerLines.length-1))*100);
  document.getElementById("readerProgressBar").style.width = pct+"%";
}

function setPlayIcon(playing){
  document.getElementById("playIcon").style.display = playing?"none":"block";
  document.getElementById("pauseIcon").style.display = playing?"block":"none";
}

function togglePlay(){
  if(currentPrayer?.youtubeId){
    isPlaying=!isPlaying;
    setPlayIcon(isPlaying);
    commandReaderYoutube(isPlaying ? "playVideo" : "pauseVideo");
    return;
  }
  isPlaying = !isPlaying;
  setPlayIcon(isPlaying);
  if(isPlaying){
    playChime(660);
    readerTimer = setInterval(()=>{
      if(currentLine < getReaderPrayerLines().length-1){
        currentLine++;
        if(activeReaderTab==="prayer") renderReaderLines();
        updateProgress();
      } else {
        clearInterval(readerTimer);
        isPlaying=false;
        setPlayIcon(false);
        markComplete();
      }
    }, LINE_SECONDS*1000);
  } else {
    clearInterval(readerTimer);
  }
}

function restartReader(){
  currentLine = 0;
  isPlaying = false;
  clearInterval(readerTimer);
  setPlayIcon(false);
  if(activeReaderTab==="prayer") renderReaderLines();
  else setReaderTab(activeReaderTab);
  updateProgress();
}

function stepReader(direction){
  currentLine = Math.max(0, Math.min(getReaderPrayerLines().length-1, currentLine+direction));
  if(activeReaderTab!=="prayer") setReaderTab("prayer");
  else renderReaderLines();
  updateProgress();
}

// for people who chanted offline (book, other app, in person) and just want
// to check today off without going through the in-app reader/play flow
function toggleTodayDirect(){
  const ds = todayStr();
  const already = state.completedDates.includes(ds);

  if(already){
    state.completedDates = state.completedDates.filter(d=>d!==ds);
    saveState();
    renderStreak();
    renderMeritStats();
    renderCalendar();
    renderBadges();
    return;
  }

  state.completedDates.push(ds);
  saveState();
  renderStreak();
  renderMeritStats();
  renderCalendar();
  renderBadges();
  playChime(880);
  spawnBurst();
  document.getElementById("completeMsg").textContent =
    `บันทึกแล้วค่ะว่าวันนี้สวดมนต์แล้ว วันนี้ครบ ${computeStreak()} วันติดต่อกันค่ะ`;
  document.getElementById("completeModal").classList.add("open");
}

function markComplete(){
  const ds = todayStr();
  const already = state.completedDates.includes(ds);
  const previousLevel = gardenLevelInfo(getMeritPoints()).level;
  const basePoints = 10;
  const meritMultiplier = isBirthdayDate() ? 5 : isWanPhraDate() ? 2 : 1;
  const earnedPoints = basePoints * meritMultiplier;
  if(!already){
    state.completedDates.push(ds);
    saveState();
  }
  state.prayerHistory = state.prayerHistory || [];
  state.prayerHistory.unshift({prayerId:currentPrayer.id,at:new Date().toISOString(),points:earnedPoints,multiplier:meritMultiplier});
  state.prayerHistory = state.prayerHistory.slice(0,50);
  saveState();
  const currentLevel = gardenLevelInfo(getMeritPoints()).level;
  if(currentLevel>previousLevel)setTimeout(()=>sendLineEvent("level_up",{level:currentLevel}),1400);
  renderStreak();
  renderMeritStats();
  renderCalendar();
  renderBadges();
  playChime(880);
  spawnBurst();
  const wanPhraBonus = meritMultiplier===5 ? ` 🎂 สุขสันต์วันเกิด รับพลังบุญ ×5 ได้ +${earnedPoints} แต้ม` : meritMultiplier===2 ? ` ✨ วันพระรับพลังบุญ ×2 ได้ +${earnedPoints} แต้ม` : ` ได้รับ +${earnedPoints} แต้มบุญ`;
  document.getElementById("completeMsg").textContent = already
    ? `วันนี้สวดครบแล้วอีกรอบ อนุโมทนาบุญด้วยนะคะ 🌸${wanPhraBonus}`
    : `สวดครบ “${currentPrayer.title}” แล้ว วันนี้ครบ ${computeStreak()} วันติดต่อกันค่ะ${wanPhraBonus}`;
  document.getElementById("completeModal").classList.add("open");
}

/* ---------------- SPARKLE BURST + CHIME ---------------- */
function spawnBurst(){
  const emojis=["✨","🌸","💗","⭐","🪷"];
  const cx = window.innerWidth/2, cy = window.innerHeight/2;
  for(let i=0;i<14;i++){
    const el = document.createElement("span");
    el.className="burst-emoji";
    el.textContent = emojis[Math.floor(Math.random()*emojis.length)];
    const angle = Math.random()*Math.PI*2;
    const dist = 80+Math.random()*120;
    el.style.left = cx+"px"; el.style.top = cy+"px";
    el.style.setProperty("--dx", Math.cos(angle)*dist+"px");
    el.style.setProperty("--dy", Math.sin(angle)*dist+"px");
    document.body.appendChild(el);
    setTimeout(()=>el.remove(), 1000);
  }
}

let audioCtx;
function playChime(freq){
  if(state.soundOn===false) return;
  try{
    audioCtx = audioCtx || new (window.AudioContext||window.webkitAudioContext)();
    const o = audioCtx.createOscillator();
    const g = audioCtx.createGain();
    o.type="sine"; o.frequency.value=freq;
    g.gain.setValueAtTime(0.0001, audioCtx.currentTime);
    const chimeVolume=(Number(state.masterVolume??70)/100)*(Number(state.notificationVolume??70)/100);
    g.gain.exponentialRampToValueAtTime(Math.max(.002,.16*chimeVolume), audioCtx.currentTime+0.02);
    g.gain.exponentialRampToValueAtTime(0.0001, audioCtx.currentTime+1.1);
    o.connect(g); g.connect(audioCtx.destination);
    o.start(); o.stop(audioCtx.currentTime+1.1);
  }catch(e){}
}

let gardenSoundNodes=[];
let gardenMasterGain=null;
let gardenBirdTimer=null;
let gardenWaterTimer=null;
let gardenSoundStarting=false;
function updateGardenSoundButton(){
  const button=document.getElementById("gardenSoundToggle");
  if(!button) return;
  button.classList.toggle("active",!!state.gardenSoundOn);
  button.setAttribute("aria-pressed",String(!!state.gardenSoundOn));
  button.innerHTML=state.gardenSoundOn?'♫ <span>เสียงธรรมชาติ</span>':'♪ <span>เสียงธรรมชาติ</span>';
}
function playGardenBird(){
  if(!audioCtx||!state.gardenSoundOn) return;
  const oscillator=audioCtx.createOscillator(), gain=audioCtx.createGain();
  const now=audioCtx.currentTime, start=720+Math.random()*360;
  oscillator.type="sine";
  oscillator.frequency.setValueAtTime(start,now);
  oscillator.frequency.exponentialRampToValueAtTime(start*1.22,now+.22);
  oscillator.frequency.exponentialRampToValueAtTime(start*.94,now+.55);
  gain.gain.setValueAtTime(.0001,now); gain.gain.exponentialRampToValueAtTime(.009,now+.12); gain.gain.exponentialRampToValueAtTime(.0001,now+.62);
  oscillator.connect(gain); gain.connect(audioCtx.destination); oscillator.start(now); oscillator.stop(now+.65);
}
function playGardenWaterDrop(){
  if(!audioCtx||!state.gardenSoundOn) return;
  const now=audioCtx.currentTime;
  const drop=audioCtx.createOscillator(), dropGain=audioCtx.createGain(), pan=audioCtx.createStereoPanner?.();
  drop.type="sine";
  drop.frequency.setValueAtTime(240+Math.random()*150,now);
  drop.frequency.exponentialRampToValueAtTime(82+Math.random()*38,now+.28);
  dropGain.gain.setValueAtTime(.0001,now);
  dropGain.gain.exponentialRampToValueAtTime(.007+Math.random()*.006,now+.035);
  dropGain.gain.exponentialRampToValueAtTime(.0001,now+.36);
  drop.connect(dropGain);
  if(pan){pan.pan.value=Math.random()*1.6-.8;dropGain.connect(pan);pan.connect(audioCtx.destination);}else dropGain.connect(audioCtx.destination);
  drop.start(now); drop.stop(now+.38);
}
async function startGardenSound(){
  if(gardenSoundNodes.length||gardenSoundStarting) return;
  gardenSoundStarting=true;
  try{
    const AudioContextClass=window.AudioContext||window.webkitAudioContext;
    if(!AudioContextClass) throw new Error("Web Audio is not supported");
    if(!audioCtx||audioCtx.state==="closed") audioCtx=new AudioContextClass();
    if(audioCtx.state!=="running") await audioCtx.resume();
    if(audioCtx.state!=="running") throw new Error("Audio context could not start");
    if(!state.gardenSoundOn) return;
    const preset=Math.max(0,Math.min(5,Number(state.soundPreset||0)));
    const soundProfiles=[
      {low:680,lowGain:.82,ripple:1500,rippleGain:.22,spray:3200,sprayGain:.08,swell:.11,drops:1800,birds:0},
      {low:480,lowGain:.48,ripple:1050,rippleGain:.3,spray:2600,sprayGain:.035,swell:.08,drops:2600,birds:0},
      {low:450,lowGain:1.15,ripple:700,rippleGain:.34,spray:1900,sprayGain:.045,swell:.045,drops:0,birds:0},
      {low:1250,lowGain:.12,ripple:3300,rippleGain:.24,spray:4700,sprayGain:.13,swell:.17,drops:0,birds:0},
      {low:760,lowGain:.16,ripple:2100,rippleGain:.08,spray:3900,sprayGain:.035,swell:.1,drops:0,birds:5200},
      {low:560,lowGain:.4,ripple:1250,rippleGain:.27,spray:2900,sprayGain:.045,swell:.085,drops:1200,birds:15000}
    ];
    const profile=soundProfiles[preset];
    const seconds=4, buffer=audioCtx.createBuffer(2,audioCtx.sampleRate*seconds,audioCtx.sampleRate);
    for(let channel=0;channel<2;channel++){
      const data=buffer.getChannelData(channel); let smooth=0;
      for(let i=0;i<data.length;i++){const white=Math.random()*2-1;smooth=smooth*.992+white*.008;data[i]=white*.06+smooth*1.35;}
    }
    const master=audioCtx.createGain(); master.gain.value=state.soundOn===false?0:.65*(Number(state.masterVolume??70)/100)*(Number(state.ambientVolume??60)/100); master.connect(audioCtx.destination); gardenMasterGain=master;
    const low=audioCtx.createBufferSource(), lowFilter=audioCtx.createBiquadFilter(), lowGain=audioCtx.createGain();
    low.buffer=buffer; low.loop=true; lowFilter.type="lowpass"; lowFilter.frequency.value=profile.low; lowGain.gain.value=profile.lowGain;
    low.connect(lowFilter); lowFilter.connect(lowGain); lowGain.connect(master); low.start();
    const ripple=audioCtx.createBufferSource(), rippleFilter=audioCtx.createBiquadFilter(), rippleGain=audioCtx.createGain();
    ripple.buffer=buffer; ripple.loop=true; rippleFilter.type="bandpass"; rippleFilter.frequency.value=profile.ripple; rippleFilter.Q.value=preset===2?.8:.45; rippleGain.gain.value=profile.rippleGain;
    ripple.connect(rippleFilter); rippleFilter.connect(rippleGain); rippleGain.connect(master); ripple.start();
    const spray=audioCtx.createBufferSource(), sprayFilter=audioCtx.createBiquadFilter(), sprayGain=audioCtx.createGain();
    spray.buffer=buffer; spray.loop=true; sprayFilter.type="highpass"; sprayFilter.frequency.value=profile.spray; sprayGain.gain.value=profile.sprayGain;
    spray.connect(sprayFilter); sprayFilter.connect(sprayGain); sprayGain.connect(master); spray.start();
    const swell=audioCtx.createOscillator(), swellGain=audioCtx.createGain(); swell.type="sine"; swell.frequency.value=profile.swell; swellGain.gain.value=preset===2?.055:.012; swell.connect(swellGain); swellGain.connect(master.gain); swell.start();
    gardenSoundNodes=[low,ripple,spray,swell];
    if(profile.drops){gardenWaterTimer=setInterval(playGardenWaterDrop,profile.drops);setTimeout(playGardenWaterDrop,500);}
    if(profile.birds){gardenBirdTimer=setInterval(playGardenBird,profile.birds);setTimeout(playGardenBird,900);}
  }catch(e){state.gardenSoundOn=false;saveState();updateGardenSoundButton();}
  finally{gardenSoundStarting=false;}
}
function stopGardenSound(){
  gardenSoundNodes.forEach(node=>{try{node.stop();}catch(e){}}); gardenSoundNodes=[];
  gardenMasterGain=null;
  clearInterval(gardenBirdTimer); gardenBirdTimer=null;
  clearInterval(gardenWaterTimer); gardenWaterTimer=null;
}

function renderGardenCharacter(){
  const points=getMeritPoints();
  const info=gardenLevelInfo(points);
  const taps=Math.max(0,Number(state.characterTaps)||0);
  const claimed=Array.isArray(state.characterGifts)?state.characterGifts:[];
  const today=(state.prayerHistory||[]).filter(item=>todayStr(new Date(item.at))===todayStr()).reduce((sum,item)=>sum+(Number(item.points)||10),0);
  const values={characterPoints:points.toLocaleString("th-TH"),characterLotus:getLotusBalance().toLocaleString("th-TH"),characterHearts:Math.min(9999,points+Math.round(taps/2)).toLocaleString("th-TH"),characterLevel:info.level,characterLevelText:`${Math.round(info.into).toLocaleString("th-TH")} / ${Math.round(info.need||0).toLocaleString("th-TH")}`,characterBond:Math.min(100,12+Math.floor(taps/25)),characterToday:today.toLocaleString("th-TH"),characterCombo:Math.max(1,Math.min(12,computeStreak()||1)),characterEnergy:Math.min(10,8+Math.floor(today/500))};
  Object.entries(values).forEach(([id,value])=>{const el=document.getElementById(id);if(el)el.textContent=value;});
  const levelBar=document.getElementById("characterLevelProgress"),bondBar=document.getElementById("characterBondProgress");
  if(levelBar)levelBar.style.width=`${info.percent}%`;if(bondBar)bondBar.style.width=`${Math.min(100,12+Math.floor(taps/25))}%`;
  const limits=[2000,5000,9000,15000,25000];
  document.querySelectorAll("[data-character-gift]").forEach(card=>{
    const index=Number(card.dataset.characterGift),isClaimed=claimed.includes(index),unlocked=taps>=limits[index];
    card.classList.toggle("locked",!unlocked&&!isClaimed);card.classList.toggle("claimed",isClaimed);
    const button=card.querySelector("button");
    if(button)button.textContent=isClaimed?"✓ ได้รับแล้ว":unlocked?"รับ":"🔒 ปลดล็อก";
  });
}

