/* ---------------- IN-APP NOTIFICATIONS (Notification API — ทำงานได้ตอนเปิดแอปอยู่เท่านั้น) ---------------- */
const NOTIFY_KEYS = ["notifyPrayer","notifyStreak","notifyMissions","notifyDailyTip","notifyAchievements","notifySpecial","notifyNews"];

function requestNotifyPermission(){
  if(!("Notification" in window)) return;
  if(Notification.permission==="default") Notification.requestPermission();
}

function notifyUser(title,body){
  if(!("Notification" in window) || Notification.permission!=="granted") return;
  try{ new Notification(title,{body,icon:"assets/lotus.png"}); }catch(e){}
}

function alreadyNotifiedToday(key){
  return (state.notifiedLog||{})[key]===todayStr();
}
function markNotifiedToday(key){
  state.notifiedLog = state.notifiedLog || {};
  state.notifiedLog[key] = todayStr();
  saveState();
}

function checkScheduledNotifications(){
  const now = new Date();
  const hhmm = `${String(now.getHours()).padStart(2,"0")}:${String(now.getMinutes()).padStart(2,"0")}`;
  if(state.notifyDailyTip && hhmm==="07:30" && !alreadyNotifiedToday("dailyTip")){
    notifyUser("ข้อคิดประจำวัน 🌿", document.getElementById("settingsDailyQuote")?.textContent || "แวะมาสวดมนต์กันนะคะวันนี้");
    markNotifiedToday("dailyTip");
  }
  if(state.notifyPrayer && state.reminderOn && state.reminderTime && hhmm===state.reminderTime && !alreadyNotifiedToday("prayerReminder")){
    notifyUser("ถึงเวลาสวดมนต์แล้วค่ะ 🙏","แวะมาสวดมนต์ตามเวลาที่ตั้งไว้กันนะคะ");
    markNotifiedToday("prayerReminder");
  }
  if(state.notifyStreak && hhmm==="20:00" && !state.completedDates.includes(todayStr()) && !alreadyNotifiedToday("streakReminder")){
    notifyUser("อย่าลืมรักษาสถิติของคุณนะคะ 🔥",`วันนี้ยังไม่ได้สวดมนต์เลย ต่อเนื่อง ${computeStreak()} วันของคุณกำลังจะขาดแล้ว`);
    markNotifiedToday("streakReminder");
  }
}

function checkDailyMissionNotification(){
  if(!state.notifyMissions || alreadyNotifiedToday("missionsReady")) return;
  notifyUser("ภารกิจวันนี้พร้อมแล้ว 🎁","แวะไปทำภารกิจในสวนบุญเพื่อรับแต้มบุญกันนะคะ");
  markNotifiedToday("missionsReady");
}

function startNotificationScheduler(){
  checkScheduledNotifications();
  checkDailyMissionNotification();
  setInterval(checkScheduledNotifications, 30000);
}

function bindNotificationPrefs(){
  const master = document.getElementById("notifyAllToggle");
  const syncMaster = ()=>{ if(master) master.checked = NOTIFY_KEYS.every(k=>state[k]!==false); };
  NOTIFY_KEYS.forEach(key=>{
    const input=document.getElementById(key);
    if(!input) return;
    input.checked = state[key] !== false;
    input.addEventListener("change",()=>{
      state[key]=input.checked; saveState();
      if(input.checked) requestNotifyPermission();
      syncMaster();
    });
  });
  syncMaster();
  master?.addEventListener("change",()=>{
    NOTIFY_KEYS.forEach(key=>{ state[key]=master.checked; const input=document.getElementById(key); if(input) input.checked=master.checked; });
    saveState();
    if(master.checked) requestNotifyPermission();
  });
}

function bindVipScreen(){
  document.querySelectorAll("#vipPlans [data-vip-plan]").forEach(button=>button.addEventListener("click",()=>{
    document.querySelectorAll("#vipPlans [data-vip-plan]").forEach(b=>b.classList.toggle("active",b===button));
  }));
  document.getElementById("vipBuyBtn")?.addEventListener("click",()=>{
    const selected=document.querySelector("#vipPlans [data-vip-plan].active")?.dataset.vipPlan||"yearly";
    state.isVip=true; state.vipPlan=selected;
    saveState();
    renderVipScreen();
    renderMembershipMenuItem();
    spawnBurst();
  });
  document.getElementById("vipCancelBtn")?.addEventListener("click",()=>{
    state.isVip=false; state.vipPlan="";
    saveState();
    renderVipScreen();
    renderMembershipMenuItem();
  });
}

function showScreen(name){
  if((name==="merit"||name==="merit-garden"||name==="vip")&&!authSession) name="settings";
  clearInterval(readerTimer);
  isPlaying = false;
  document.body.classList.toggle("register-mode",name==="register");
  document.body.classList.toggle("guide-mode",name==="guide");
  document.body.classList.toggle("notification-mode",name==="notifications");
  document.body.classList.toggle("sound-settings-mode",name==="sound-settings");
  document.body.classList.toggle("community-mode",name==="community"||name==="encouragement");
  document.body.classList.toggle("garden-mode",name==="merit-garden"||name==="garden-rewards"||name==="garden-decorate"||name==="garden-character");
  document.body.classList.toggle("character-mode",name==="garden-character");
  document.body.classList.remove("photo-view");
  const viewLabel=document.querySelector("#decorateViewToggle span");
  if(viewLabel) viewLabel.textContent="มุมมอง";
  document.body.classList.toggle("decorate-mode",name==="garden-decorate");
  document.querySelectorAll(".screen").forEach(s=>s.classList.remove("active"));
  document.getElementById("screen-"+name).classList.add("active");
  document.querySelectorAll(".nav-item").forEach(b=>b.classList.remove("active"));
  document.querySelectorAll(`.nav-item[data-nav="${name}"]`).forEach(b=>b.classList.add("active"));
  if(name==="encouragement")document.querySelector('.nav-item[data-nav="community"]')?.classList.add("active");
  if(name==="register") document.querySelector('.nav-item[data-nav="settings"]')?.classList.add("active");
  window.scrollTo({top:0, behavior:name==="register"?"auto":"smooth"});
  if(name==="register"){
    document.documentElement.scrollTop=0;
    document.body.scrollTop=0;
    document.querySelector(".app-shell")?.scrollTo?.(0,0);
  }

  if(name==="merit"){ renderMeritStats(); renderCalendar(); renderBadges(); renderFavList(); }
  if(name==="merit-garden"){renderMeritGarden();if(state.gardenSoundOn&&state.soundOn!==false)startGardenSound();}
  else if(name==="sound-settings"){state.gardenSoundOn=false;stopGardenSound();document.querySelectorAll(".sound-presets .playing").forEach(button=>button.classList.remove("playing"));}
  else if(state.soundContinuous===false||state.soundOn===false){state.gardenSoundOn=false;stopGardenSound();}
  if(name==="garden-rewards") renderGardenRewards(document.querySelector("[data-reward-filter].active")?.dataset.rewardFilter||"all");
  if(name==="garden-decorate") renderGardenDecorator(document.querySelector("[data-decor-filter].active")?.dataset.decorFilter||"all");
  if(name==="garden-character") renderGardenCharacter();
  if(name==="community") renderCommunity();
  if(name==="encouragement") renderEncouragement();
  if(name==="vip") renderVipScreen();
  if(name==="prayers") setPrayerLibraryTab(activeLibraryTab);
  if(name==="assistant") document.getElementById("assistantResult")?.classList.remove("show");
}

const DEEP_LINK_SCREENS=new Set([
  "home","prayers","merit","profile","settings","assistant",
  "merit-garden","community","encouragement"
]);
let initialDeepLinkApplied=false;

function applyInitialDeepLink(){
  if(initialDeepLinkApplied)return;
  initialDeepLinkApplied=true;
  const params=new URLSearchParams(window.location.search);
  const sharedPrayerIds=(params.get("share_prayers")||"").split(",").map(id=>id.trim()).filter(id=>findPrayer(id));
  if(sharedPrayerIds.length){
    activeReaderSequence=sharedPrayerIds;
    activeReaderSequenceIndex=0;
    openReader(sharedPrayerIds[0],{preserveSequence:true});
    const sharedName=params.get("share_name");
    if(sharedName)document.getElementById("readerCat").textContent=`ชุดสวดจากเพื่อน · ${sharedName}`;
    return;
  }
  const requested=params.get("page");
  if(!requested||!DEEP_LINK_SCREENS.has(requested))return;
  showScreen(requested);
  if(requested==="merit-garden"&&params.get("section")==="missions"){
    setTimeout(()=>document.querySelector(".garden-missions")?.scrollIntoView({behavior:"auto",block:"start"}),250);
  }
}

/* ---------------- SETTINGS ---------------- */
function applyFontSize(size){
  [document.documentElement,document.body].forEach(el=>{
    el.classList.remove("font-small","font-large");
    if(size==="small") el.classList.add("font-small");
    if(size==="large") el.classList.add("font-large");
  });
}

function applyTheme(theme){
  document.body.classList.remove("theme-pink","theme-yellow","theme-mint");
  if(theme!=="purple") document.body.classList.add(`theme-${theme}`);
  document.querySelectorAll("#themeOptions button").forEach(btn=>btn.classList.toggle("active", btn.dataset.theme===theme));
}

function initSettings(){
  state.theme = state.theme || "purple";
  applyTheme(state.theme);
  document.querySelectorAll("#themeOptions button").forEach(btn=>{
    btn.addEventListener("click", ()=>{
      state.theme = btn.dataset.theme;
      saveState();
      applyTheme(state.theme);
    });
  });
  document.querySelectorAll("#fontSizeOptions button").forEach(btn=>{
    if(btn.dataset.size===state.fontSize) btn.classList.add("active"); else btn.classList.remove("active");
    btn.addEventListener("click", ()=>{
      state.fontSize = btn.dataset.size; saveState();
      document.querySelectorAll("#fontSizeOptions button").forEach(b=>b.classList.toggle("active", b===btn));
      applyFontSize(state.fontSize);
    });
  });
  applyFontSize(state.fontSize);

  const profileNameInput = document.getElementById("profileNameInput");
  const profileMessageInput = document.getElementById("profileMessageInput");
  let pendingProfileTheme = state.profileTheme || "pink";
  const applyProfileImages = (gender,profileTheme=pendingProfileTheme)=>{
    const isMale = ["ชาย","ผู้ชาย","male","m"].includes(String(gender||"").trim().toLowerCase());
    const characterLevel=gardenLevelInfo(getMeritPoints()).level;
    const characterTier=Math.max(1,Math.min(10,Math.floor((characterLevel-1)/10)+1));
    const scoreCharacter=`assets/community-characters/${isMale?"male":"female"}-${characterTier}.png?v=ba3`;
    const themeImages = {
      pink:{female:"assets/hero-pink-female.png",male:"assets/hero-pink-male.png"},
      purple:{female:"assets/hero-purple-female.png",male:"assets/hero-purple-male.png"},
      blue:{female:"assets/hero-blue-female.png",male:"assets/hero-blue-male.png"},
      green:{female:"assets/hero-green-female.png",male:"assets/hero-green-male.png"}
    };
    const selectedImages = themeImages[profileTheme] || themeImages.pink;
    document.querySelectorAll("[data-profile-avatar]").forEach(image=>image.src=scoreCharacter);
    document.querySelectorAll("[data-gender-hero]").forEach(image=>image.src=isMale ? selectedImages.male : selectedImages.female);
    document.querySelectorAll("[data-garden-character]").forEach(image=>image.src=scoreCharacter);
    document.querySelectorAll("#profileThemeOptions button").forEach(button=>button.classList.toggle("active",button.dataset.profileTheme===profileTheme));
  };
  const renderProfileSetting = ()=>{
    document.getElementById("settingsProfileName").textContent = state.profileName || "แก้ไขโปรไฟล์";
    document.getElementById("settingsProfileMessage").textContent = state.profileMessage || "เพิ่มชื่อและข้อความทักทายของคุณ";
    document.getElementById("profileDisplayName").textContent = state.profileName || "เมตตา มณีจันทร์";
    document.getElementById("profileDisplayBio").textContent = state.profileMessage || "ขอให้ทุกวันเป็นวันที่ใจสงบ 💗";
    const meritPoints = getMeritPoints();
    document.getElementById("profileLevel").textContent = `Lv.${getGardenProgress().level}`;
    document.getElementById("profilePoints").textContent = meritPoints.toLocaleString("th-TH");
    document.getElementById("profileStreak").textContent = `${computeStreak()} วัน`;
    pendingProfileTheme = state.profileTheme || "pink";
    applyProfileImages(state.profileGender || "หญิง",pendingProfileTheme);
    renderMembershipMenuItem();
  };
  renderProfileSetting();
  document.getElementById("editProfileBtn").addEventListener("click",()=>{
    renderProfileSetting(); document.querySelector(".profile-menu").style.display="block"; document.getElementById("profileInlineEdit").classList.remove("open"); showScreen("profile");
  });
  document.getElementById("personalInfoBtn").addEventListener("click",()=>{
    profileNameInput.value=state.profileName||""; profileMessageInput.value=state.profileMessage||""; document.getElementById("profileBirthDate").value=state.profileBirthDate||""; document.getElementById("profileEmail").value=state.profileEmail||"";
    pendingProfileTheme=state.profileTheme||"pink"; document.querySelectorAll('[name="profileGender"]').forEach(input=>input.checked=input.value===(state.profileGender||"หญิง")); applyProfileImages(state.profileGender||"หญิง",pendingProfileTheme); document.querySelector(".profile-menu").style.display="none"; document.getElementById("profileInlineEdit").classList.add("open");
  });
  document.getElementById("lineConnectBtn").addEventListener("click",async()=>{
    if(!authSession){
      showLineLinkMessage("กรุณาเข้าสู่ระบบก่อนเชื่อมบัญชี LINE ค่ะ");
      showScreen("register");
      return;
    }
    const button=document.getElementById("lineConnectBtn");
    button.disabled=true;
    try{
      const response=await fetch(`${LINE_BOT_API}/api/bot-info`);
      const result=await response.json();
      if(!response.ok||!result.chat_url)throw new Error("เปิด LINE Bot ไม่สำเร็จ");
      location.href=result.chat_url;
    }catch(error){showLineLinkMessage(error.message);}finally{button.disabled=false;}
  });
  document.getElementById("lineLinkSuccessOk").addEventListener("click",()=>{
    const button=document.getElementById("lineLinkSuccessOk");
    document.getElementById("lineLinkSuccessModal").classList.remove("open");
    if(button.dataset.notifyLine==="true")sendLineEvent("account_linked");
  });
  document.getElementById("profileEditBack").addEventListener("click",()=>{ pendingProfileTheme=state.profileTheme||"pink"; applyProfileImages(state.profileGender||"หญิง",pendingProfileTheme); document.getElementById("profileInlineEdit").classList.remove("open"); document.querySelector(".profile-menu").style.display="block"; });
  document.querySelectorAll('[name="profileGender"]').forEach(input=>input.addEventListener("change",()=>applyProfileImages(input.value,pendingProfileTheme)));
  document.querySelectorAll("#profileThemeOptions button").forEach(button=>button.addEventListener("click",()=>{ pendingProfileTheme=button.dataset.profileTheme; applyProfileImages(document.querySelector('[name="profileGender"]:checked')?.value||state.profileGender||"หญิง",pendingProfileTheme); }));
  document.getElementById("profileForm").addEventListener("submit",event=>{
    event.preventDefault();
    state.profileName = profileNameInput.value.trim();
    state.profileMessage = profileMessageInput.value.trim();
    state.profileGender=document.querySelector('[name="profileGender"]:checked')?.value||"หญิง"; state.profileTheme=pendingProfileTheme; state.profileBirthDate=document.getElementById("profileBirthDate").value; state.profileEmail=document.getElementById("profileEmail").value.trim();
    saveState();
    renderProfileSetting();
    renderHero();
    document.getElementById("profileInlineEdit").classList.remove("open"); document.querySelector(".profile-menu").style.display="block";
  });

  document.querySelectorAll("#goalOptions button").forEach(btn=>{
    if(Number(btn.dataset.goal)===state.goal) btn.classList.add("active"); else btn.classList.remove("active");
    btn.addEventListener("click", ()=>{
      state.goal = Number(btn.dataset.goal); saveState();
      document.getElementById("goalValue").textContent = `${state.goal} วัน`;
      document.querySelectorAll("#goalOptions button").forEach(b=>b.classList.toggle("active", b===btn));
      renderStreak();
    });
  });
  document.getElementById("goalValue").textContent = `${state.goal} วัน`;

  const toggle = document.getElementById("reminderToggle");
  const timeInput = document.getElementById("reminderTime");
  const timePickerModal = document.getElementById("timePickerModal");
  const timeHour = document.getElementById("timeHour");
  const timeMinute = document.getElementById("timeMinute");
  const selectedTime = document.getElementById("selectedTime");
  if(toggle) toggle.checked = state.reminderOn;
  if(!["20:00","21:00","22:00"].includes(state.reminderTime))state.reminderTime="20:00";
  timeInput.value = state.reminderTime;
  selectedTime.textContent = state.reminderTime;
  timeHour.innerHTML = [20,21,22].map(i=>`<option value="${i}">${i}</option>`).join("");
  timeMinute.innerHTML = '<option value="00">00</option>';
  document.getElementById("timePickerBtn").addEventListener("click", ()=>{
    const [hour,minute] = timeInput.value.split(":");
    timeHour.value = hour; timeMinute.value = minute;
    timePickerModal.classList.add("open");
  });
  document.getElementById("timePickerCancel").addEventListener("click", ()=>timePickerModal.classList.remove("open"));
  document.getElementById("timePickerSave").addEventListener("click", ()=>{
    state.reminderTime = `${timeHour.value}:${timeMinute.value}`;
    timeInput.value = state.reminderTime;
    selectedTime.textContent = state.reminderTime;
    saveState();
    timePickerModal.classList.remove("open");
  });
  timePickerModal.addEventListener("click", e=>{if(e.target===timePickerModal) timePickerModal.classList.remove("open");});
  toggle?.addEventListener("change", ()=>{
    state.reminderOn = toggle.checked; saveState();
    if(toggle.checked) requestNotifyPermission();
  });
  // หมายเหตุ: id="soundToggle" ผูก event ไว้แล้วใน bindSoundSettings() (หน้าการตั้งค่าเสียง) ไม่ต้องผูกซ้ำที่นี่

  document.getElementById("resetBtn").addEventListener("click", ()=>{
    if(confirm("ล้างข้อมูลการสวดมนต์ทั้งหมดใช่ไหมคะ? การกระทำนี้ย้อนกลับไม่ได้")){
      state = {...DEFAULT_STATE,completedDates:[],favorites:[],prayerHistory:[],customPrayerSets:[]};
      saveState();
      applyTheme(state.theme);
      applyFontSize(state.fontSize);
      renderAll();
      showScreen("home");
    }
  });
}

function bindSoundSettings(){
  const screen=document.getElementById("screen-sound-settings");
  if(!screen)return;
  const master=screen.querySelector(".sound-master input[type=range]");
  const volumeRanges=[...screen.querySelectorAll(".sound-volume-group input[type=range]")];
  const soundToggle=document.getElementById("soundToggle");
  const continuous=screen.querySelector(".sound-continuous input");
  const playButton=screen.querySelector(".sound-play");
  const saveStatus=document.getElementById("soundAutosaveStatus");
  const presets=[...screen.querySelectorAll(".sound-presets button")];
  const volumeKeys=["chantVolume","ambientVolume","notificationVolume"];
  const refreshVolume=()=>{
    master.value=state.masterVolume??70;
    master.nextElementSibling.textContent=`${master.value}%`;
    volumeRanges.forEach((range,index)=>{range.value=state[volumeKeys[index]]??[80,60,70][index];range.nextElementSibling.textContent=`${range.value}%`;});
    continuous.checked=state.soundContinuous!==false;
    presets.forEach((button,index)=>{const selected=index===Number(state.soundPreset||0);button.classList.toggle("active",selected);button.classList.toggle("playing",selected&&state.gardenSoundOn);});
    if(playButton)playButton.textContent=state.gardenSoundOn?"❚❚":"▶";
  };
  const updateLiveGain=()=>{if(gardenMasterGain)gardenMasterGain.gain.value=state.soundOn===false?0:.65*(Number(state.masterVolume)/100)*(Number(state.ambientVolume)/100);};
  let saveStatusTimer;
  const autoSave=()=>{
    if(saveStatus){saveStatus.textContent="กำลังบันทึกลงฐานข้อมูล...";saveStatus.classList.add("saving");}
    clearTimeout(saveStatusTimer);
    saveState(result=>{
      if(!saveStatus)return;
      if(result.saved)saveStatus.textContent="✓ บันทึกลงฐานข้อมูลแล้ว";
      else if(result.reason==="guest")saveStatus.textContent="บันทึกในเครื่องแล้ว · เข้าสู่ระบบเพื่อบันทึกฐานข้อมูล";
      else saveStatus.textContent="บันทึกในเครื่องแล้ว · รอซิงก์ฐานข้อมูล";
      saveStatus.classList.remove("saving");
    });
  };
  master.addEventListener("input",()=>{state.masterVolume=Number(master.value);master.nextElementSibling.textContent=`${master.value}%`;updateLiveGain();autoSave();});
  volumeRanges.forEach((range,index)=>range.addEventListener("input",()=>{state[volumeKeys[index]]=Number(range.value);range.nextElementSibling.textContent=`${range.value}%`;updateLiveGain();autoSave();}));
  soundToggle.addEventListener("change",()=>{state.soundOn=soundToggle.checked;if(!state.soundOn){state.gardenSoundOn=false;stopGardenSound();}updateLiveGain();autoSave();refreshVolume();});
  continuous.addEventListener("change",()=>{state.soundContinuous=continuous.checked;autoSave();});
  presets.forEach((button,index)=>button.addEventListener("click",async()=>{const isPlaying=state.gardenSoundOn&&Number(state.soundPreset||0)===index;if(isPlaying){state.gardenSoundOn=false;stopGardenSound();autoSave();refreshVolume();return;}state.soundPreset=index;state.soundOn=true;state.gardenSoundOn=true;soundToggle.checked=true;stopGardenSound();autoSave();refreshVolume();playChime([440,520,600,680,760,840][index]||520);await startGardenSound();refreshVolume();}));
  refreshVolume();
}

/* ---------------- BIND EVENTS ---------------- */
function bindNav(){
  document.querySelectorAll(".nav-item").forEach(btn=>{
    if(btn.dataset.nav) btn.addEventListener("click", ()=> showScreen(btn.dataset.nav));
  });
  document.querySelectorAll("[data-nav]").forEach(el=>{
    if(!el.classList.contains("nav-item")){
      el.addEventListener("click", ()=>{
        showScreen(el.dataset.nav);
        if(el.dataset.scrollTarget){
          setTimeout(()=>document.getElementById(el.dataset.scrollTarget)?.scrollIntoView({behavior:"smooth",block:"start"}),250);
        }
      });
    }
  });
  document.getElementById("mainPrayerBtn").addEventListener("click", ()=>{
    openReader("jinapanjara");
  });
}

function bindReaderControls(){
  const continuousToggle = document.getElementById("continuousToggle");
  continuousToggle.checked = Boolean(state.continuousOn);
  continuousToggle.addEventListener("change", ()=>{
    state.continuousOn = continuousToggle.checked;
    saveState();
  });
  document.querySelectorAll("[data-reader-tab]").forEach(btn=>{
    btn.addEventListener("click", ()=> setReaderTab(btn.dataset.readerTab));
  });
  document.querySelectorAll("[data-reader-media]").forEach(btn=>{
    btn.addEventListener("click",()=>setReaderMediaMode(btn.dataset.readerMedia));
  });
  document.getElementById("readerPlay").addEventListener("click", togglePlay);
  document.getElementById("readerRestart").addEventListener("click", restartReader);
  document.getElementById("readerPrev").addEventListener("click", ()=> stepReader(-1));
  document.getElementById("readerNext").addEventListener("click", ()=> stepReader(1));
  document.getElementById("readerSetPrev").addEventListener("click",()=>navigateReaderSet(-1));
  document.getElementById("readerSetNext").addEventListener("click",()=>navigateReaderSet(1));
  document.getElementById("readerDone").addEventListener("click", ()=> stepReader(1));
  document.getElementById("readerCountRound").addEventListener("click",()=>{
    readerRoundCount+=1;
    document.getElementById("readerRoundCount").textContent=String(readerRoundCount);
  });
  document.getElementById("readerFav").addEventListener("click", ()=> toggleFavorite(currentPrayer.id));
  document.getElementById("completeClose").addEventListener("click", ()=>{
    document.getElementById("completeModal").classList.remove("open");
    closeReader();
  });
}

function bindSearch(){
  document.getElementById("searchInput").addEventListener("input", (e)=>{
    searchTerm = e.target.value;
    renderPrayerList();
  });
}

function bindBell(){
  const bellBtn=document.getElementById("bellBtn");
  if(!bellBtn) return;
  bellBtn.addEventListener("click", ()=>{
    const isSettingsOpen = document.getElementById("screen-settings").classList.contains("active");
    showScreen(isSettingsOpen ? "home" : "settings");
  });
}

function bindCheckin(){
  document.getElementById("checkinBtn").addEventListener("click", toggleTodayDirect);
}

function bindAssistant(){
  let assistantMode = "focus";
  const focusRecommendations = {
    "เงินและโชคลาภ":["millionaire-mantra","sivali-worship","lakshmi-worship"],
    "งานและความสำเร็จ":["maha-chakraphat","wish","ratanattaya-praise"],
    "ความรักและเมตตา":["metta-self","karaniya-metta-sutta","merit-dedication"],
    "ใจสงบผ่อนคลาย":["karaniya-metta-sutta","metta-self","bedtime-prayer"],
    "คุ้มครองปกป้อง":["bahum-mahaka","vesavana-worship","jinapanjara-full"],
    "สุขภาพสิริมงคล":["ratanattaya-praise","bahum-mahaka","merit-dedication"],
    "ก่อนนอนหลับสบาย":["bedtime-prayer","metta-self","merit-dedication"],
    "เริ่มต้นวันใหม่":["namotassa","ratanattaya-praise","maha-chakraphat"]
  };
  const picker = document.getElementById("assistantPrayerPicker");
  const searchWrap = document.getElementById("assistantPrayerSearchWrap");
  const searchInput = document.getElementById("assistantPrayerSearch");
  const assistantReminder = document.getElementById("assistantReminder");
  const assistantContinuous = document.getElementById("assistantContinuous");
  picker.innerHTML = PRAYERS.filter(prayer=>prayer.id!=="popular").map(prayer=>`<button data-value="${prayer.id}"><img src="${getPrayerIcon(prayer)}" alt=""><b>${prayer.title}</b><i>✓</i></button>`).join("");
  const prayerModal = document.getElementById("assistantPrayerModal");
  const closePrayerModal = ()=>{
    prayerModal.classList.remove("open");
    prayerModal.setAttribute("aria-hidden","true");
  };
  const openPrayerModal = prayer=>{
    if(!prayer) return;
    const closingStart = prayer.lines.findIndex(line=>String(line).includes("คำอธิษฐานหลังสวด"));
    const previewLines = (closingStart>=0 ? prayer.lines.slice(0,closingStart) : prayer.lines).filter(line=>!isReaderTranslationLine(line));
    document.getElementById("assistantModalImage").src = getPrayerIcon(prayer);
    document.getElementById("assistantModalTitle").textContent = prayer.title;
    document.getElementById("assistantModalDesc").textContent = prayer.desc || "";
    document.getElementById("assistantModalContent").innerHTML = previewLines.map(line=>{
      const isSection = String(line).startsWith("## ");
      return `<p class="${isSection ? "section" : ""}">${isSection ? String(line).slice(3) : line}</p>`;
    }).join("") || "<p>ยังไม่มีเนื้อหาบทสวด</p>";
    prayerModal.classList.add("open");
    prayerModal.setAttribute("aria-hidden","false");
  };
  let suppressPrayerPickerClick = false;
  picker.addEventListener("click",event=>{
    if(!suppressPrayerPickerClick) return;
    event.preventDefault();
    event.stopImmediatePropagation();
    suppressPrayerPickerClick = false;
  },true);
  picker.querySelectorAll("button[data-value]").forEach(button=>{
    let holdTimer = null;
    let didHold = false;
    let startX = 0;
    let startY = 0;
    const cancelHold = ()=>{ clearTimeout(holdTimer); holdTimer=null; };
    button.addEventListener("pointerdown",event=>{
      startX=event.clientX; startY=event.clientY;
      didHold=false;
      cancelHold();
      holdTimer=setTimeout(()=>{
        didHold=true;
        suppressPrayerPickerClick=true;
        openPrayerModal(findPrayer(button.dataset.value));
        if(navigator.vibrate) navigator.vibrate(25);
      },550);
    });
    button.addEventListener("pointermove",event=>{ if(Math.hypot(event.clientX-startX,event.clientY-startY)>10) cancelHold(); });
    button.addEventListener("pointerup",()=>{ cancelHold(); if(didHold) setTimeout(()=>{ suppressPrayerPickerClick=false; },350); });
    button.addEventListener("pointercancel",cancelHold);
    button.addEventListener("pointerleave",cancelHold);
    button.addEventListener("contextmenu",event=>event.preventDefault());
  });
  document.getElementById("assistantPrayerModalClose").addEventListener("click",closePrayerModal);
  prayerModal.addEventListener("click",event=>{ if(event.target===prayerModal) closePrayerModal(); });
  document.addEventListener("keydown",event=>{ if(event.key==="Escape" && prayerModal.classList.contains("open")) closePrayerModal(); });
  assistantReminder.classList.toggle("active",Boolean(state.reminderOn));
  assistantReminder.setAttribute("aria-pressed",String(Boolean(state.reminderOn)));
  document.getElementById("assistantReminderText").textContent = `ทุกวัน ${state.reminderTime || "19:00"} น.`;
  assistantContinuous.checked = Boolean(state.continuousOn);

  let assistantFocusOrder = [...document.querySelectorAll('[data-assistant-group="focus"] .active')].map(item=>item.dataset.value);
  let assistantFocusPrayerOrder = [];
  const selectedFocuses = ()=>assistantFocusOrder.filter(value=>document.querySelector(`[data-assistant-group="focus"] button[data-value="${value}"]`)?.classList.contains("active"));
  const selectedPrayers = ()=>{
    if(assistantMode==="prayers") return assistantPrayerOrder.filter(id=>picker.querySelector(`button[data-value="${id}"]`)?.classList.contains("active")).map(findPrayer).filter(Boolean);
    const ids = [...new Set(selectedFocuses().flatMap(focus=>focusRecommendations[focus] || []))];
    assistantFocusPrayerOrder = [...assistantFocusPrayerOrder.filter(id=>ids.includes(id)),...ids.filter(id=>!assistantFocusPrayerOrder.includes(id))];
    return assistantFocusPrayerOrder.map(findPrayer).filter(Boolean);
  };
  const refreshAssistantPreview = ()=>{
    const prayers = selectedPrayers();
    const focuses = selectedFocuses();
    const time = document.querySelector('[data-assistant-group="time"] .active')?.dataset.value || "ช่วงที่สะดวก";
    const totalMinutes = prayers.reduce((sum,prayer)=>sum+(Number.parseInt(prayer.duration,10) || 0),0);
    const editingSet = (state.customPrayerSets || []).find(item=>String(item.id)===String(editingAssistantSetId));
    const focusTitle = {
      "เงินและโชคลาภ":"เงิน",
      "งานและความสำเร็จ":"งาน",
      "ความรักและเมตตา":"ความรัก",
      "ใจสงบผ่อนคลาย":"ใจสงบ",
      "คุ้มครองปกป้อง":"คุ้มครอง",
      "สุขภาพสิริมงคล":"สุขภาพ",
      "ก่อนนอนหลับสบาย":"ก่อนนอน",
      "เริ่มต้นวันใหม่":"เริ่มวันใหม่"
    };
    const title = assistantMode==="prayers" ? (editingSet?.name || time) : focuses.length>1 ? `ชุดสวด ${focuses.length} เป้าหมาย – ${time}` : `ชุดสวด${focusTitle[focuses[0]] || "สิริมงคล"} – ${time}`;
    document.getElementById("assistantPreviewTitle").textContent = title;
    document.getElementById("assistantPreviewDuration").textContent = prayers.length ? `ใช้เวลาประมาณ ${totalMinutes} นาที` : "ยังไม่ได้เลือกบทสวด";
    const prayerList = document.getElementById("assistantPrayerList");
    prayerList.innerHTML = prayers.length ? prayers.map((prayer,index)=>`<li class="sortable" data-prayer-id="${prayer.id}"><span>${index+1}</span><b class="assistant-prayer-name">${prayer.title}</b><small>${prayer.duration}</small><i class="assistant-drag-handle" role="button" aria-label="ลากเพื่อเรียงลำดับ">⠿</i></li>`).join("") : '<li class="assistant-empty">เลือกบทสวดเพื่อเพิ่มลงในชุด</li>';
    bindAssistantPreviewSorting(prayerList);
  };

  const syncPrayerOrderFromPreview = list=>{
    const reorderedIds = [...list.querySelectorAll("li[data-prayer-id]")].map(item=>item.dataset.prayerId);
    if(!reorderedIds.length) return;
    if(assistantMode==="prayers") assistantPrayerOrder = reorderedIds;
    else assistantFocusPrayerOrder = reorderedIds;
    refreshAssistantPreview();
  };
  const captureVisiblePrayerOrder = ()=>{
    const reorderedIds = [...document.querySelectorAll("#assistantPrayerList li[data-prayer-id]")].map(item=>item.dataset.prayerId);
    if(!reorderedIds.length) return;
    if(assistantMode==="prayers") assistantPrayerOrder = reorderedIds;
    else assistantFocusPrayerOrder = reorderedIds;
  };
  const bindAssistantPreviewSorting = list=>{
    let draggedItem = null;
    list.querySelectorAll("li.sortable").forEach(item=>{
      const handle = item.querySelector(".assistant-drag-handle");
      handle?.addEventListener("pointerdown",event=>{
        if(event.button!==undefined && event.button!==0) return;
        draggedItem=item;
        item.classList.add("dragging");
        handle.setPointerCapture(event.pointerId);
        window.getSelection()?.removeAllRanges();
        event.preventDefault();
      });
      handle?.addEventListener("pointermove",event=>{
        if(!draggedItem) return;
        const edge=56;
        if(event.clientY<edge) window.scrollBy(0,-Math.min(14,edge-event.clientY));
        else if(event.clientY>window.innerHeight-edge) window.scrollBy(0,Math.min(14,event.clientY-(window.innerHeight-edge)));

        const siblings=[...list.querySelectorAll("li[data-prayer-id]")].filter(entry=>entry!==draggedItem);
        const next=siblings.find(entry=>event.clientY < entry.getBoundingClientRect().top + entry.getBoundingClientRect().height/2);
        if(next) list.insertBefore(draggedItem,next);
        else list.appendChild(draggedItem);
        event.preventDefault();
      });
      const finishPointerDrag = event=>{ if(!draggedItem) return; if(handle.hasPointerCapture(event.pointerId)) handle.releasePointerCapture(event.pointerId); draggedItem.classList.remove("dragging"); draggedItem=null; syncPrayerOrderFromPreview(list); };
      handle?.addEventListener("pointerup",finishPointerDrag);
      handle?.addEventListener("pointercancel",finishPointerDrag);
    });
  };

  document.querySelectorAll("[data-assistant-group]").forEach(group=>{
    group.querySelectorAll("button").forEach(button=>button.addEventListener("click", ()=>{
      if(group.dataset.multiple==="true"){
        button.classList.toggle("active");
        if(group.dataset.assistantGroup==="prayers"){
          if(button.classList.contains("active")){ if(!assistantPrayerOrder.includes(button.dataset.value)) assistantPrayerOrder.push(button.dataset.value); }
          else assistantPrayerOrder = assistantPrayerOrder.filter(id=>id!==button.dataset.value);
        }
        if(group.dataset.assistantGroup==="focus"){
          if(button.classList.contains("active")){ if(!assistantFocusOrder.includes(button.dataset.value)) assistantFocusOrder.push(button.dataset.value); }
          else assistantFocusOrder = assistantFocusOrder.filter(value=>value!==button.dataset.value);
        }
      }
      else{
        group.querySelectorAll("button").forEach(item=>item.classList.remove("active"));
        button.classList.add("active");
      }
      refreshAssistantPreview();
    }));
  });
  document.querySelectorAll("#assistantModeTabs button").forEach(button=>button.addEventListener("click", ()=>{
    assistantMode = button.dataset.mode;
    document.querySelectorAll("#assistantModeTabs button").forEach(item=>item.classList.toggle("active",item===button));
    document.querySelector('[data-assistant-group="focus"]').style.display = assistantMode==="focus" ? "grid" : "none";
    picker.classList.toggle("open",assistantMode==="prayers");
    searchWrap.classList.toggle("open",assistantMode==="prayers");
    document.getElementById("assistantModeTitle").textContent = assistantMode==="focus" ? "เลือกสิ่งที่คุณอยากโฟกัสในช่วงนี้ (เลือกได้หลายข้อ)" : "เลือกบทสวดที่ต้องการเพิ่มในชุด (เลือกได้หลายบท)";
    refreshAssistantPreview();
  }));
  searchInput.addEventListener("input",()=>{
    const query = searchInput.value.trim().toLocaleLowerCase("th");
    picker.querySelectorAll("button").forEach(button=>{
      const prayer = findPrayer(button.dataset.value);
      const haystack = `${prayer?.title || ""} ${prayer?.category || ""} ${prayer?.desc || ""}`.toLocaleLowerCase("th");
      button.hidden = Boolean(query) && !haystack.includes(query);
    });
  });
  assistantReminder.addEventListener("click",()=>{
    state.reminderOn = !state.reminderOn;
    assistantReminder.classList.toggle("active",state.reminderOn);
    assistantReminder.setAttribute("aria-pressed",String(state.reminderOn));
    const settingsToggle = document.getElementById("reminderToggle");
    if(settingsToggle) settingsToggle.checked = state.reminderOn;
    saveState();
  });
  assistantContinuous.addEventListener("change",()=>{
    state.continuousOn = assistantContinuous.checked;
    const readerToggle = document.getElementById("continuousToggle");
    if(readerToggle) readerToggle.checked = state.continuousOn;
    saveState();
  });
  document.getElementById("assistantCreate").addEventListener("click", ()=>{
    // Read the visible list immediately before saving. On some mobile browsers
    // dragend/pointerup can be skipped when the user taps Save right after a drag.
    captureVisiblePrayerOrder();
    const prayers = selectedPrayers();
    const result = document.getElementById("assistantResult");
    if(prayers.length){
      if(!Array.isArray(state.customPrayerSets)) state.customPrayerSets=[];
      const existingSet = state.customPrayerSets.find(item=>String(item.id)===String(editingAssistantSetId));
      if(existingSet){
        existingSet.prayerIds = prayers.map(prayer=>prayer.id);
        existingSet.totalMinutes = prayers.reduce((sum,prayer)=>sum+(Number.parseInt(prayer.duration,10) || 0),0);
        existingSet.updatedAt = new Date().toISOString();
      }else{
        state.customPrayerSets.push({
          id:Date.now(),
          name:document.getElementById("assistantPreviewTitle").textContent,
          prayerIds:prayers.map(prayer=>prayer.id),
          totalMinutes:prayers.reduce((sum,prayer)=>sum+(Number.parseInt(prayer.duration,10) || 0),0),
          createdAt:new Date().toISOString()
        });
      }
      saveState();
      renderMyPrayerSets();
      result.textContent = existingSet ? `✨ อัปเดตชุดสวด ${prayers.length} บทเรียบร้อยแล้ว` : `✨ บันทึกชุดสวด ${prayers.length} บทแล้ว ดูได้ที่ บทสวด > บทสวดของฉัน`;
      editingAssistantSetId = null;
      document.getElementById("assistantCreate").innerHTML = '<span>✦</span> สร้างชุดสวดของฉัน <small>เริ่มต้นสวดได้ทันที</small>';
      document.querySelectorAll('[data-assistant-group="focus"] button.active').forEach(button=>button.classList.remove("active"));
      assistantFocusOrder = [];
      assistantFocusPrayerOrder = [];
      picker.querySelectorAll("button.active").forEach(button=>button.classList.remove("active"));
      assistantPrayerOrder = [];
      searchInput.value = "";
      picker.querySelectorAll("button").forEach(button=>button.hidden=false);
      refreshAssistantPreview();
      setPrayerLibraryTab("mine");
      showScreen("prayers");
    }else result.textContent = "กรุณาเลือกเป้าหมายหรือบทสวดอย่างน้อย 1 รายการค่ะ";
    result.classList.add("show");
  });
  refreshAssistantPreview();
}

function bindPrayerLibrary(){
  document.querySelectorAll("#prayerLibraryTabs button").forEach(button=>button.addEventListener("click",()=>setPrayerLibraryTab(button.dataset.libraryTab)));
  document.getElementById("myPrayerBack").addEventListener("click",renderMyPrayerSets);
  document.getElementById("myPrayerRenameSet").addEventListener("click",openPlaylistRenameModal);
  document.getElementById("playlistRenameCancel").addEventListener("click",()=>document.getElementById("playlistRenameModal").classList.remove("open"));
  document.getElementById("playlistRenameSave").addEventListener("click",savePlaylistRename);
  document.getElementById("playlistRenameInput").addEventListener("keydown",event=>{if(event.key==="Enter")savePlaylistRename();});
  document.getElementById("myPrayerShareSet").addEventListener("click",openPlaylistShareModal);
  document.getElementById("playlistShareClose").addEventListener("click",()=>document.getElementById("playlistShareModal").classList.remove("open"));
  document.getElementById("myPrayerDeleteSet").addEventListener("click",()=>deleteMyPrayerSet(editingPrayerSetId));
  document.getElementById("myPrayerEditSet").addEventListener("click",()=>editPrayerSetInAssistant(editingPrayerSetId));
}

